    13, 13, 13, 13, 13, 13, 13, 13, 13, 13, 13, 13, 13, 13, 13, 13, 3,  3,  3,  3,  3,  3,  3,  3,  3,  3,  3,  3,  3,  3,  3,  3,
};

/// Gets the Bidi Class for a code point
pub fn getBidiClass(cp: Codepoint) BidiClass {
    if (cp > 0x10FFFF) return .L;
    const block = @as(usize, cp >> 8);
    if (block >= bidi_stage1.len) return .L;
    const offset = @as(usize, cp & 0xFF);
    const stage2_idx = bidi_stage1[block] + offset;
    if (stage2_idx >= bidi_stage2.len) return .L;
    return @enumFromInt(bidi_stage2[stage2_idx]);
}

/// Checks if a bidi class is a strong type (L, R, AL)
pub fn isStrong(class: BidiClass) bool {
    return class == .L or class == .R or class == .AL;
}

/// Checks if a bidi class is right-to-left (R, AL)
pub fn isRightToLeft(class: BidiClass) bool {
    return class == .R or class == .AL;
}

/// Gets the base direction for a string (first strong character)
pub fn getBaseDirection(text: []const u8) ?BidiClass {
    var iter = std.unicode.Utf8Iterator{ .bytes = text, .i = 0 };
    while (iter.nextCodepoint()) |cp| {
        const class = getBidiClass(cp);
        if (isStrong(class)) {
            return class;
        }
    }
    return null;
}
